proposed_mapping_js:
/* eslint-disable */
/**
 * Babele registerMapping layer for the Alien RPG packages.
 *
 * Targets (all three are Adventure-type packs holding ONE Adventure document):
 *   alienrpg.alien-rpg-system                          (system alienrpg 4.1.13)
 *   alien-evolved-corerules.alien-evolved-core-rules   (module 1.0.2)
 *   alien-evolved-starterset.alien-evolved-starter-set (module 1.0.2)
 *
 * This layer only ENRICHES Babele 2.9.1 built-in defaults. Everything it does
 * not mention (Adventure.folders/journals/scenes/macros/playlists/cards,
 * JournalEntry(.pages), RollTable(.results), Region/RegionBehavior,
 * ActiveEffect, Card) keeps the built-in behaviour on purpose.
 *
 * Register during the `babele.init` hook, before the runtime session exists:
 *   Hooks.once('babele.init', (babele) => {
 *     babele.registerConverters(ALIENRPG_CONVERTERS);
 *     babele.registerMapping(ALIENRPG_MAPPINGS);
 *   });
 */

const isStr = (v) => typeof v === 'string' && v.trim().length > 0;

/**
 * Normalize whatever Babele hands a function converter as `runtime`
 * (a DocumentTranslationScope, a CompendiumRuntime, or a bare object)
 * into something exposing localMappedCompendiumFor()/currentCompendium().
 */
function asRuntime(runtime) {
  if (!runtime) return null;
  if (typeof runtime.runtime === 'function') return runtime.runtime();
  if (runtime.runtime && typeof runtime.runtime.localMappedCompendiumFor === 'function') return runtime.runtime;
  return runtime;
}

/* ------------------------------------------------------------------ *
 * Converter 1 - RollTable NAME REFERENCE fields.
 *
 * `system.rTables` / `system.cTables` on creature actors do not store an id;
 * they store the RollTable NAME. module/helpers/rollTableData.mjs builds the
 * <select> options as {key: table.name, label: table.name}, and
 * module/documents/actor.mjs:1839 resolves the roll with
 * game.tables.getName(dataset.atttype). Translating these strings by hand
 * would silently drift from the translated RollTable names and break both the
 * dropdown selection and the creature attack / critical injury roll.
 *
 * So resolve the value from the SAME translation block that renames the
 * tables: the Adventure `tables` field below is declared with `expose: true`,
 * which publishes its EmbeddedCompendium (metadata.type === 'RollTable') into
 * the per-document translation scope, where localMappedCompendiumFor
 * ('RollTable') finds it. An explicit `rollTable` / `critTable` entry in the
 * actor's own translation still wins.
 * ------------------------------------------------------------------ */
export function alienRollTableRef(value, translation, source, contextCompendium, allTranslations, runtime = {}) {
  if (!isStr(value) || value === 'None') return value;  // 'None' is a magic value, never translate it
  if (isStr(translation)) return translation;
  const rt = asRuntime(runtime);
  const tables = rt?.localMappedCompendiumFor?.('RollTable');
  if (!tables) return value;
  const translated = tables.translateField?.('name', { name: value }, rt);
  return isStr(translated) ? translated : value;
}
alienRollTableRef.extract = (value) => (isStr(value) && value !== 'None' ? value : undefined);

/* ------------------------------------------------------------------ *
 * Converter 2 - prototypeToken.name.
 *
 * Babele's built-in Actor mapping declares
 *   tokenName: {path:'prototypeToken.name', converter:'name'}
 * and `name` is Converters.mappedField('name'), which DISCARDS the
 * `tokenName` translation and returns the translated `name` field instead.
 * This is a strict superset: use the tokenName translation when present,
 * otherwise fall back to the built-in behaviour so a token is never left in
 * English. In all three Alien packs prototypeToken.name === actor.name for
 * 74/74 actors, so the fallback is the normal path.
 * ------------------------------------------------------------------ */
export function alienTokenName(value, translation, source, contextCompendium, allTranslations, runtime = {}) {
  if (isStr(translation)) return translation;
  const pack = contextCompendium ?? asRuntime(runtime)?.currentCompendium?.() ?? null;
  const fallback = pack?.translateField?.('name', source, runtime);
  return isStr(fallback) ? fallback : value;
}
alienTokenName.extract = (value) => (isStr(value) ? value : undefined);

export const ALIENRPG_CONVERTERS = {
  alienRollTableRef,
  alienTokenName,
};

/* ------------------------------------------------------------------ *
 * Document mappings.
 *
 * Item/Actor subtype selection uses `_variants` (`_when: {path:'type', ...}`)
 * so that (a) one translation key `description` can point at a different
 * source path per subtype, and (b) documents from OTHER systems sharing this
 * GLOBAL mapping layer never match an alienrpg-only path. Every variant that
 * redefines the built-in key `description` also carries an `exists` guard on
 * its own path, because MappingBlock#activeFields REPLACES a base field with a
 * matching variant field of the same key - without the guard a dnd5e/pf2e
 * item of type "weapon"/"armor"/"item" would lose Babele's built-in
 * system.description.value mapping.
 * ------------------------------------------------------------------ */
export const ALIENRPG_MAPPINGS = {

  /* ---------------- Adventure ---------------- *
   * name / description / caption / folders / journals / scenes / macros /
   * playlists / cards keep the built-in defaults. Only the two collections
   * that must become visible to sibling collections are redeclared. */
  "Adventure": {
    // expose:true publishes the Item EmbeddedCompendium into the document
    // translation scope, so actor-embedded items inherit these translations by
    // name. That covers 155/180 (86.1%) of actor-embedded items and
    // 48,181/52,998 chars (90.9%). _stats.compendiumSource covers 0%: every
    // embedded source uuid is either a world uuid (144/180) or points at a
    // pack id that no longer exists (36/180).
    "items": {
      "path": "items",
      "converter": "document",
      "documentType": "Item",
      "cardinality": "many",
      "expose": true
    },
    // expose:true is what lets alienRollTableRef resolve system.rTables /
    // system.cTables against the translated table names.
    "tables": {
      "path": "tables",
      "converter": "document",
      "documentType": "RollTable",
      "cardinality": "many",
      "expose": true
    }
  },

  /* ---------------- Item ---------------- */
  "Item": {
    "name": "name",
    "effects": {
      "path": "effects",
      "converter": "document",
      "documentType": "ActiveEffect",
      "cardinality": "many"
    },
    "_variants": [
      /* HTML body edited through <prose-mirror name="system.attributes.comment.value">
         and enriched in module/sheets/item-sheet.mjs. 307 docs / 99,697 chars. */
      {
        "_when": {
          "all": [
            { "path": "type", "in": ["item", "weapon", "armor", "spacecraftmods", "spacecraftweapons"] },
            { "path": "system.attributes.comment.value", "exists": true }
          ]
        },
        "description": "system.attributes.comment.value"
      },
      /* HTML body under system.general.comment.value. 100 docs / 19,595 chars. */
      {
        "_when": {
          "all": [
            { "path": "type", "in": ["agenda", "talent", "specialty"] },
            { "path": "system.general.comment.value", "exists": true }
          ]
        },
        "description": "system.general.comment.value"
      },
      /* weapon-only free text: "Pistol", "Rifle", "Heavy weapon". */
      {
        "_when": { "path": "type", "equals": "weapon" },
        "weaponClass": "system.attributes.class.value"
      },
      /* spacecraftmods-only free text: "Added Hardpoint, size I". */
      {
        "_when": { "path": "type", "equals": "spacecraftmods" },
        "capacity": "system.attributes.capacity.value"
      },
      /* skill-stunts is the ONLY type whose data model declares
         system.description (item-stunts.mjs). Babele's built-in Item default
         points at system.description.value, which does not exist anywhere in
         this system. */
      {
        "_when": {
          "all": [
            { "path": "type", "equals": "skill-stunts" },
            { "path": "system.description", "exists": true }
          ]
        },
        "description": "system.description"
      },
      /* planet-system gazetteer entries. */
      {
        "_when": {
          "all": [
            { "path": "type", "equals": "planet-system" },
            { "path": "system.details.classification.value", "exists": true }
          ]
        },
        "description": "system.misc.description.value",
        "commonName": "system.header.commonName.value",
        "starSystem": "system.header.system.value",
        "sector": "system.header.sector.value",
        "location": "system.header.location.value",
        "affiliation": "system.details.affiliation.value",
        "classification": "system.details.classification.value",
        "climate": "system.details.climate.value",
        "meanTemperature": "system.details.meanTemperature.value",
        "terrain": "system.details.terrain.value",
        "colonies": "system.details.colonies.value",
        "keyResources": "system.details.keyResources.value"
      },
      /* crit-inj / spacecraft-crit / colony-initiative have 0 documents in the
         three packs today, but their data models declare these as HTML/string
         free text, so they are mapped for forward compatibility. */
      {
        "_when": {
          "all": [
            { "path": "type", "equals": "crit-inj" },
            { "path": "system.attributes.effects", "exists": true }
          ]
        },
        "description": "system.attributes.effects",
        "healingTime": "system.attributes.healingtime.value"
      },
      {
        "_when": {
          "all": [
            { "path": "type", "equals": "spacecraft-crit" },
            { "path": "system.header.effects", "exists": true }
          ]
        },
        "description": "system.header.effects",
        "repairRoll": "system.header.repairroll",
        "damage": "system.header.damage.value"
      },
      {
        "_when": {
          "all": [
            { "path": "type", "equals": "colony-initiative" },
            { "path": "system.header.comment", "exists": true }
          ]
        },
        "description": "system.header.comment",
        "initiativeType": "system.header.type"
      }
    ]
  },

  /* ---------------- Actor ---------------- */
  "Actor": {
    "name": "name",
    "tokenName": {
      "path": "prototypeToken.name",
      "converter": "alienTokenName"
    },
    "items": {
      "path": "items",
      "converter": "document",
      "documentType": "Item",
      "cardinality": "many"
    },
    "effects": {
      "path": "effects",
      "converter": "document",
      "documentType": "ActiveEffect",
      "cardinality": "many"
    },
    "_variants": [
      /* system.notes is the base-actor HTMLField, enriched by every sheet.
         Babele's built-in Actor default points at
         system.details.biography.value, which does not exist in this system.
         NOTE: `vehicles` is deliberately absent - actor-vehicle.mjs REDECLARES
         schema.notes as SchemaField({notes: StringField}), so on vehicles
         system.notes is the OBJECT {notes: "..."} and writing a string there
         would replace a SchemaField with a scalar. It is handled below. */
      {
        "_when": {
          "path": "type",
          "in": ["character", "synthetic", "creature", "spacecraft", "colony", "planet", "territory"]
        },
        "notes": "system.notes"
      },
      {
        "_when": { "path": "type", "in": ["character", "synthetic"] },
        "appearance": "system.general.appearance.value",
        "adhocItems": "system.adhocitems",
        "signatureItem": "system.general.sigItem.value",
        "agenda": "system.general.agenda.value",
        "relationshipOne": "system.general.relOne.value",
        "relationshipTwo": "system.general.relTwo.value"
      },
      {
        "_when": { "path": "type", "equals": "creature" },
        /* PLAIN TEXT in a <textarea> (creature-general.hbs:14): newlines are
           significant and HTML must NOT be introduced. 30 docs / 81,617 chars,
           the largest single actor field in the corpus. */
        "special": "system.general.special.value",
        "rollTable": { "path": "system.rTables", "converter": "alienRollTableRef" },
        "critTable": { "path": "system.cTables", "converter": "alienRollTableRef" }
      },
      {
        "_when": { "path": "type", "equals": "vehicles" },
        /* PLAIN TEXT <textarea> (vehicle-general.hbs:9) at the SAME path that
           is rich HTML on the item side - deliberately a separate variant. */
        "comment": "system.attributes.comment.value",
        "misc": "system.general.misc.value",
        /* vehicles-only: notes is nested one level deeper than on every other
           actor type (actor-vehicle.mjs:130). */
        "notes": "system.notes.notes"
      },
      {
        "_when": { "path": "type", "equals": "spacecraft" },
        "misc": "system.general.misc.value",
        "manufacturer": "system.attributes.manufacturer",
        "model": "system.attributes.model",
        "ai": "system.attributes.ai",
        "modules": "system.attributes.modules",
        "armaments": "system.attributes.armaments"
      },
      /* colony / planet / territory: 0 documents in the three packs; mapped
         from the data models so a future colony supplement is covered. */
      {
        "_when": { "path": "type", "equals": "colony" },
        "misc": "system.general.misc.value",
        "colonyName": "system.header.colonyname",
        "location": "system.attributes.location",
        "mission": "system.attributes.mission",
        "established": "system.attributes.established",
        "sponsor": "system.attributes.sponsor",
        "commander": "system.attributes.commander",
        "economyDirector": "system.attributes.economydirector",
        "statsNotes": "system.stats.notes"
      },
      {
        "_when": { "path": "type", "equals": "planet" },
        "misc": "system.general.misc.value",
        "colonyName": "system.header.colonyname",
        "parentStar": "system.attributes.parentstar",
        "radiation": "system.attributes.radiation",
        "planetSize": "system.attributes.planetsize",
        "atmosphere": "system.attributes.atmosphere",
        "hydrosphere": "system.attributes.hydrosphere",
        "dayLength": "system.attributes.daylength",
        "axialTilt": "system.attributes.axialtilt",
        "gravity": "system.attributes.gravity",
        "climate": "system.attributes.climate",
        "globalFeature": "system.attributes.globalfeature",
        "orbitalPeriod": "system.attributes.orbitalperiod",
        "personality": "system.attributes.personality",
        "northPole": "system.attributes.northpole",
        "equator": "system.attributes.equator",
        "southPole": "system.attributes.southpole",
        "nhWest": "system.attributes.nhwest",
        "nhSouth": "system.attributes.nhsouth",
        "nhEast": "system.attributes.nheast",
        "shEast": "system.attributes.sheast",
        "shWest": "system.attributes.shwest"
      },
      {
        "_when": { "path": "type", "equals": "territory" },
        "sectors": "system.sectors.value",
        "comment": "system.comment.value"
      }
    ]
  },

  /* ---------------- Scene ---------------- *
   * name / drawings / notes / regions keep the built-in defaults
   * (textCollection for drawings + notes, document converter for regions).
   * navName and tokens are genuine gaps in Babele's default Scene mapping;
   * both are empty in these packs today but cost nothing to declare. */
  "Scene": {
    "navName": "navName",
    "tokens": {
      "path": "tokens",
      "converter": "nameCollection"
    }
  }
};
